/* Returns the 12-byte entry at entryIndex of a menu (negative means last; out of range falls back to entry 0), or 0 if menu is NULL. */ s32 getMenuEntry(void *menu, s8 entryIndex) { s32 ret; s8 clampedIndex; clampedIndex = entryIndex; if (menu == NULL) return 0; else { if (entryIndex < 0) clampedIndex = *(u8 *)((char *)menu + 0x19) - 1; { s32 count = *(volatile u8 *)((char *)menu + 0x19); s32 selected = (s8)clampedIndex; s32 base = *(s32 *)menu; u32 mask = -(selected < count); s8 index = mask & clampedIndex; ret = base + index * 12; } } return ret; }
